property.value:
let $isElement := function($node, $element) {
      exists($node/self::VariableAccess[@Name = $element]
        | $node/self::MethodCall[@MethodName = 'getKey'][ArgumentList/@Size = 0][*[1][self::VariableAccess][@Name = $element]])
    },
    $side := function($test, $element) {
      if ($test/self::InfixExpression[@Operator = ('<', '<=', '>', '>=')][$isElement(*[1], $element)])
      then (if ($test/@Operator = ('>', '>=')) then 'low' else 'high')
      else if ($test/self::InfixExpression[@Operator = ('<', '<=', '>', '>=')][$isElement(*[2], $element)])
      then (if ($test/@Operator = ('<', '<=')) then 'low' else 'high')
      else 'none'
    }
return
//ForeachStatement
  [*[2][pmd-java:typeIs('java.util.SortedSet')]
   or *[2][self::MethodCall][@MethodName = ('keySet', 'navigableKeySet', 'entrySet')][ArgumentList/@Size = 0]
     [*[1][pmd-java:typeIs('java.util.SortedMap')]]]
  [let $element := LocalVariableDeclaration//VariableId/@Name,
       $body := *[3]/(self::Block[count(*) = 1]/* | self::IfStatement)
   return exists($body[self::IfStatement][count(*) = 2]
     [*[1][self::InfixExpression][@Operator = '&&'][count(*) = 2][let $sides := (for $test in * return $side($test, $element)) return $sides = 'low' and $sides = 'high']]
     [*[2]/descendant-or-self::*[self::ReturnStatement or self::BreakStatement]])]
